package com.tekwatt.support.controller;import com.tekwatt.support.dto.*;import com.tekwatt.support.entity.*;import com.tekwatt.support.service.MaintenanceService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/support")public class MaintenanceController{private final MaintenanceService service;public MaintenanceController(MaintenanceService s){service=s;}@PostMapping("/maintenance-jobs")@ResponseStatus(HttpStatus.CREATED)MaintenanceJob job(@Valid@RequestBody MaintenanceJobRequest r){return service.create(r);}@GetMapping("/maintenance-jobs")List<MaintenanceJob>jobs(@RequestParam UUID tenantId){return service.jobs(tenantId);}@PatchMapping("/maintenance-jobs/{id}/status")MaintenanceJob status(@PathVariable UUID id,@RequestBody Map<String,String>b){return service.jobStatus(id,b.get("status"));}@PostMapping("/amc-contracts")@ResponseStatus(HttpStatus.CREATED)AmcContract contract(@Valid@RequestBody AmcContractRequest r){return service.create(r);}@GetMapping("/amc-contracts")List<AmcContract>contracts(@RequestParam UUID tenantId){return service.contracts(tenantId);}@PatchMapping("/amc-contracts/{id}/status")AmcContract statusContract(@PathVariable UUID id,@RequestBody Map<String,String>b){return service.contractStatus(id,b.get("status"));}}
